<?php
require_once __DIR__.'/common.php';
$history=defined('CAJA_HISTORY');$centre=caja_centre($_GET);$centreId=(int)$centre['id_centro'];
$closeId=$history?0:caja_id($_GET,'id_cierre_caja');$period=caja_period($centreId,$closeId);$closed=$period['close']!==null;
$allTotals=$history?null:caja_totals($period);
$mode=(string)app_value($_GET,'forma',app_value($_GET,'mostrar_todos','0')==='1'?'todas':($history?'todas':'0'));
if($mode!=='todas'&&!array_key_exists($mode,caja_methods()))$mode='todas';
$search=trim(app_text(app_value($_GET,'buscar')));if(mb_strlen($search)>100)$search=mb_substr($search,0,100);
$from=(string)app_value($_GET,'desde',$history?date('Y-m-01'):'');$to=(string)app_value($_GET,'hasta',$history?date('Y-m-t'):'');
// Old bookmarks retain their date and academic-year filters.
if($history&&!isset($_GET['desde']))foreach(['i'=>'from','f'=>'to'] as $suffix=>$var){$day=caja_id($_GET,'dia_'.$suffix);$month=caja_id($_GET,'mes_'.$suffix);$year=caja_id($_GET,'ano_'.$suffix);if($year&&checkdate($month,$day,$year))$$var=sprintf('%04d-%02d-%02d',$year,$month,$day);}
foreach([$from,$to] as $date)if($date!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)||date('Y-m-d',strtotime($date))!==$date))caja_fail('Revisa las fechas del filtro.');
if($from!==''&&$to!==''&&$from>$to)caja_fail('La fecha inicial no puede ser posterior a la final.');
$course=$history?caja_id($_GET,'curso_mostrado'):0;
[$where,$types,$values]=$history?['p.id_centro=?','i',[$centreId]]:caja_where($period);
if($mode!=='todas'){$where.=' AND p.forma_pago=?';$types.='s';$values[]=$mode;}
if($from!==''){$where.=' AND p.fecha_pago>=?';$types.='s';$values[]=$from;}
if($to!==''){$where.=' AND p.fecha_pago<=?';$types.='s';$values[]=$to;}
if($course){$where.=' AND a.id_curso=?';$types.='i';$values[]=$course;}
if($search!==''){$where.=" AND (CONCAT_WS(' ',u.Nombre,u.Apellido1,u.Apellido2) LIKE ? OR p.comentario LIKE ? OR CONCAT_WS('-',f.serie,f.num_factura) LIKE ?)";$types.='sss';array_push($values,'%'.$search.'%','%'.$search.'%','%'.$search.'%');}
$joins=" FROM pagos_a_cuenta p LEFT JOIN facturas_emitidas f ON f.id_factura=p.id_factura LEFT JOIN alumnos a ON a.id_alumno=f.id_cliente AND COALESCE(f.tipo_cliente,0)=0 LEFT JOIN usuarios u ON u.id_usuario=a.id_usuario ";
$filtered=caja_rows("SELECT COUNT(*) AS n,COALESCE(SUM(CASE WHEN ROUND(p.importe_pago*100)*p.signo>=0 THEN ROUND(p.importe_pago*100)*p.signo ELSE 0 END),0) AS income,COALESCE(SUM(CASE WHEN ROUND(p.importe_pago*100)*p.signo<0 THEN -ROUND(p.importe_pago*100)*p.signo ELSE 0 END),0) AS expense $joins WHERE $where",$types,$values)[0];
$perPage=50;$pages=max(1,(int)ceil((int)$filtered['n']/$perPage));$page=min($pages,max(1,caja_id($_GET,'pagina',1)));$offset=($page-1)*$perPage;
$rows=caja_rows("SELECT p.*,f.serie,f.num_factura,f.tipo_cliente,a.id_alumno,CONCAT_WS(' ',u.Nombre,u.Apellido1,u.Apellido2) AS alumno,CONCAT_WS(' ',staff.Nombre,staff.Apellido1,staff.Apellido2) AS empleado $joins LEFT JOIN usuarios staff ON staff.id_usuario=p.anotado_por WHERE $where ORDER BY p.fecha_pago DESC,p.hora_pago DESC,p.id_pago DESC LIMIT $perPage OFFSET $offset",$types,$values);
$details=[];$ids=array_values(array_unique(array_filter(array_map(fn($r)=>(int)$r['id_factura'],$rows))));
if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));foreach(caja_rows("SELECT id_factura,cantidad,concepto FROM detalles_factura WHERE id_factura IN ($marks)",str_repeat('i',count($ids)),$ids) as $d)$details[(int)$d['id_factura']][]=$d;}
$movements=$history?[]:caja_rows("SELECT m.*,CONCAT_WS(' ',u.Nombre,u.Apellido1,u.Apellido2) AS empleado FROM movimientos_caja m LEFT JOIN usuarios u ON u.id_usuario=m.anotado_por WHERE m.id_centro=? AND m.id_cierre_anterior=? ORDER BY m.fecha DESC,m.hora DESC,m.id_movimiento DESC",'ii',[$centreId,$period['previous_id']]);
$paymentMethods=caja_rows("SELECT p.forma_pago,COALESCE(SUM(CASE WHEN ROUND(p.importe_pago*100)*p.signo>=0 THEN ROUND(p.importe_pago*100)*p.signo ELSE 0 END),0) AS income,COALESCE(SUM(CASE WHEN ROUND(p.importe_pago*100)*p.signo<0 THEN -ROUND(p.importe_pago*100)*p.signo ELSE 0 END),0) AS expense $joins WHERE $where GROUP BY p.forma_pago",$types,$values);
$closes=$history?[]:caja_rows('SELECT id_cierre,fecha,hora FROM cierres_caja WHERE id_centro=? ORDER BY id_cierre DESC LIMIT 100','i',[$centreId]);
$centres=app_centres();if(app_can_change_centre())array_unshift($centres,['id_centro'=>0,'nombre_centro'=>'Central']);
function caja_page_url($changes){return (defined('CAJA_HISTORY')?'resumen_caja.php':'listado_caja.php').'?'.http_build_query(array_merge($_GET,$changes));}
caja_header($history?'Historial de cobros':($closed?'Cierre de caja':'Caja activa'));
?>
<p class="caja-subtitle"><?=app_escape($centre['nombre_centro'])?> &middot; <?php if($history){ ?>Consulta por fechas, alumno o forma de pago.<?php }elseif($closed){ ?>Cerrada el <?=caja_date($period['close']['fecha'])?> a las <?=app_escape(substr((string)$period['close']['hora'],0,5))?>. Solo consulta.<?php }else{ ?><?php if($period['previous']){ ?>Abierta desde el cierre del <?=caja_date($period['previous']['fecha'])?> a las <?=app_escape(substr((string)$period['previous']['hora'],0,5))?>.<?php }else{ ?>Primer periodo de caja.<?php } ?> El efectivo se calcula con todos los movimientos de este periodo.<?php } ?></p>
<?php if(app_value($_GET,'resultado')==='saved'){ ?><div class="caja-alert success" role="status">El movimiento se ha guardado correctamente.</div><?php }elseif(app_value($_GET,'resultado')==='closed'){ ?><div class="caja-alert success" role="status">Caja cerrada. El efectivo que has dejado ya figura en la nueva caja.</div><?php }elseif(app_value($_GET,'resultado')==='deleted'){ ?><div class="caja-alert success" role="status">Movimiento eliminado de la caja abierta.</div><?php } ?>
<section class="caja-card"><form class="caja-toolbar" method="get" action="<?=$history?'resumen_caja.php':'listado_caja.php'?>">
<label>Centro<select name="id_centro_caja"><?php foreach($centres as $c){ ?><option value="<?=(int)$c['id_centro']?>" <?=(int)$c['id_centro']===$centreId?'selected':''?>><?=app_escape($c['nombre_centro'])?></option><?php } ?></select></label>
<?php if(!$history){ ?><label>Periodo<select name="id_cierre_caja"><option value="0">Caja activa</option><?php foreach($closes as $c){ ?><option value="<?=(int)$c['id_cierre']?>" <?=(int)$c['id_cierre']===$closeId?'selected':''?>>Cierre <?=caja_date($c['fecha'])?> &middot; <?=app_escape(substr((string)$c['hora'],0,5))?></option><?php }if($closed&&!in_array($closeId,array_column($closes,'id_cierre'))){ ?><option value="<?=$closeId?>" selected>Cierre <?=caja_date($period['close']['fecha'])?></option><?php } ?></select></label><?php } ?>
<label>Forma de pago<select name="forma"><option value="todas" <?=$mode==='todas'?'selected':''?>>Todas</option><?php foreach(caja_methods() as $id=>$label){ ?><option value="<?=$id?>" <?=$mode===(string)$id?'selected':''?>><?=app_escape($label)?></option><?php } ?></select></label>
<label>Desde<input type="date" name="desde" value="<?=app_escape($from)?>"></label><label>Hasta<input type="date" name="hasta" value="<?=app_escape($to)?>"></label>
<label>Alumno, concepto o factura<input type="search" name="buscar" maxlength="100" value="<?=app_escape($search)?>" placeholder="Buscar en los movimientos"></label>
<?php if($history){ ?><label>Curso<select name="curso_mostrado"><option value="0">Todos</option><?php foreach(caja_rows('SELECT id_curso,nombre FROM cursos_academicos ORDER BY fecha_inicio DESC') as $c){ ?><option value="<?=(int)$c['id_curso']?>" <?=(int)$c['id_curso']===$course?'selected':''?>><?=app_escape($c['nombre'])?></option><?php } ?></select></label><?php } ?>
<button type="submit" class="primary">Aplicar filtros</button><a href="<?=$history?'resumen_caja.php':'listado_caja.php'?>?id_centro_caja=<?=$centreId?>">Limpiar</a></form>
<?php if(!$history){ ?><div class="caja-actions"><?php if($period['previous_id']){ ?><a class="caja-button" href="<?=app_escape(caja_page_url(['id_cierre_caja'=>$period['previous_id'],'pagina'=>1]))?>">&larr; Cierre anterior</a><?php }if($closed){$next=caja_rows('SELECT id_cierre FROM cierres_caja WHERE id_centro=? AND id_cierre>? ORDER BY id_cierre LIMIT 1','ii',[$centreId,$closeId]); ?><a class="caja-button" href="<?=app_escape(caja_page_url(['id_cierre_caja'=>(int)($next[0]['id_cierre']??0),'pagina'=>1]))?>"><?=$next?'Cierre siguiente':'Volver a caja activa'?> &rarr;</a><?php } ?></div><?php } ?></section>
<div class="caja-stats"><article class="caja-stat"><span>Ingresos mostrados</span><strong class="caja-positive"><?=caja_money((int)$filtered['income'])?></strong><small>Seg&uacute;n los filtros seleccionados</small></article><article class="caja-stat"><span>Gastos y devoluciones</span><strong class="caja-negative"><?=caja_money((int)$filtered['expense'])?></strong><small>Seg&uacute;n los filtros seleccionados</small></article><article class="caja-stat"><span>Balance de movimientos</span><strong><?=caja_money((int)$filtered['income']-(int)$filtered['expense'])?></strong><small><?=(int)$filtered['n']?> movimientos encontrados</small></article><article class="caja-stat highlight"><span><?=$history?'Periodo consultado':($closed?'Efectivo contado':'Efectivo en caja')?></span><?php if($history){ ?><strong style="font-size:21px"><?=caja_date($from)?></strong><small>Hasta <?=caja_date($to)?></small><?php }else{ ?><strong><?=caja_money($closed?(int)round((float)$period['close']['importe_al_cierre_real']*100):$allTotals['cash'])?></strong><small><?=$closed?'Recuento registrado en este cierre':'Saldo completo, independiente de los filtros'?></small><?php } ?></article></div>
<?php if(!$history&&!$closed){ ?><section class="caja-card"><h2>Registrar una operaci&oacute;n</h2><div class="caja-actions"><a class="caja-button primary" href="/facturacion/listado_alumnos.php">Cobrar una factura</a><a class="caja-button" href="nuevo_gasto.php?id_centro_caja=<?=$centreId?>">Anotar gasto</a><a class="caja-button" href="nuevo_ingreso.php?id_centro_caja=<?=$centreId?>">Otro ingreso</a><a class="caja-button" href="nueva_aportacion.php?id_centro_caja=<?=$centreId?>">Aportar efectivo</a><a class="caja-button" href="nueva_retirada.php?id_centro_caja=<?=$centreId?>">Retirar efectivo</a><a class="caja-button" href="cerrar_caja.php?id_centro_caja=<?=$centreId?>">Hacer recuento y cerrar</a></div><p class="caja-note">Los ingresos y gastos registran actividad. Las aportaciones y retiradas solo mueven efectivo: no se suman a los ingresos del negocio.</p></section><?php } ?>
<section class="caja-card"><h2>Cobros, gastos y devoluciones</h2><p class="caja-note">Los m&aacute;s recientes aparecen primero. Abre el concepto para ver los detalles.</p><div class="caja-rotate">Para leer todas las columnas, gira el dispositivo o desliza la tabla.<button type="button" data-landscape>Ver en horizontal</button></div><div class="caja-table-wrap" tabindex="0" aria-label="Tabla de ingresos y gastos"><table class="caja-table"><thead><tr><th>Fecha</th><th>Alumno / familia</th><th>Concepto</th><th>Forma de pago</th><th>Tipo</th><th class="number">Importe</th><th>Acciones</th></tr></thead><tbody>
<?php foreach($rows as $row){$signed=(int)round((float)$row['importe_pago']*100)*(int)$row['signo'];$invoice=(int)$row['id_factura'];$name=trim((string)$row['alumno']);if($name==='')$name=$invoice&&((int)$row['tipo_cliente']===1)?'Alumno externo':($invoice?'Alumno no disponible':'Movimiento manual');$concept=trim((string)$row['comentario']);if($concept==='')$concept=$invoice?'Cobro de factura':($signed<0?'Gasto de caja':'Ingreso de caja'); ?>
<tr><td class="date"><?=caja_date($row['fecha_pago'])?><small><?=app_escape(substr((string)$row['hora_pago'],0,5))?></small></td><td class="person"><?=app_escape($name)?><?php if($invoice){ ?><small>Factura <?=app_escape(trim((string)$row['serie'].'-'.(string)$row['num_factura'],'-'))?></small><?php } ?></td><td class="concept"><details><summary><?=app_escape($concept)?></summary><?php foreach($details[$invoice]??[] as $d){ ?><p><?=app_escape($d['cantidad'])?> &times; <?=app_escape($d['concepto'])?></p><?php } ?><p>Registrado por: <?=app_escape(trim((string)$row['empleado'])?:'No disponible')?></p><?php if($row['observaciones_pago']){ ?><p><?=nl2br(app_escape($row['observaciones_pago']))?></p><?php } ?></details></td><td><?=app_escape(caja_method($row['forma_pago']))?></td><td><span class="caja-tag <?=$signed<0?'expense':'income'?>"><?=$signed<0?($invoice?'Devoluci&oacute;n':'Gasto'):'Ingreso'?></span></td><td class="number <?=$signed<0?'caja-negative':'caja-positive'?>"><?=caja_money($signed)?></td><td><?php if($invoice){ ?><a class="caja-button" href="/pdf/recibos.php?id_pago=<?=(int)$row['id_pago']?>&amp;id_factura=<?=$invoice?>" target="_blank" rel="noopener">Ver recibo</a><?php }elseif(!$history&&!$closed){ ?><form method="post" class="caja-inline-form" action="eliminar_detalle_caja.php" data-confirm="Se eliminar&aacute; este movimiento manual de la caja abierta. &iquest;Continuar?"><input type="hidden" name="id_centro_caja" value="<?=$centreId?>"><input type="hidden" name="id_pago" value="<?=(int)$row['id_pago']?>"><input type="hidden" name="caja_token" value="<?=caja_token('delete_payment',$centreId,$period['previous_id'])?>"><button type="submit" class="danger">Eliminar</button></form><?php }else{ ?><span class="caja-note">Solo consulta</span><?php } ?></td></tr><?php }if(!$rows){ ?><tr><td colspan="7" class="caja-empty">No hay movimientos con estos filtros.</td></tr><?php } ?>
</tbody></table></div><nav class="caja-pagination" aria-label="Paginaci&oacute;n"><span>P&aacute;gina <?=$page?> de <?=$pages?> &middot; 50 por p&aacute;gina</span><div class="caja-actions"><?php if($page>1){ ?><a class="caja-button" href="<?=app_escape(caja_page_url(['pagina'=>$page-1]))?>">Anterior</a><?php }if($page<$pages){ ?><a class="caja-button" href="<?=app_escape(caja_page_url(['pagina'=>$page+1]))?>">Siguiente</a><?php } ?></div></nav></section>
<div class="caja-grid"><section class="caja-card"><h2>Resumen por forma de pago</h2><p class="caja-note">Importes correspondientes a los filtros. Las salidas incluyen gastos y devoluciones.</p><div class="caja-table-wrap"><table class="caja-table caja-payment-summary"><thead><tr><th>Forma de pago</th><th class="number">Ingresos</th><th class="number">Salidas</th><th class="number">Balance</th></tr></thead><tbody><?php foreach($paymentMethods as $method){ ?><tr><td><?=app_escape(caja_method($method['forma_pago']))?></td><td class="number"><?=caja_money((int)$method['income'])?></td><td class="number"><?=caja_money((int)$method['expense'])?></td><td class="number"><?=caja_money((int)$method['income']-(int)$method['expense'])?></td></tr><?php }if(!$paymentMethods){ ?><tr><td colspan="4" class="caja-empty">Sin movimientos.</td></tr><?php } ?></tbody></table></div></section>
<?php if(!$history){ ?><section class="caja-card"><h2><?=$closed?'Recuento del cierre':'C&oacute;mo se calcula el efectivo'?></h2><div class="caja-summary"><span>Cobros menos gastos en efectivo</span><strong><?=caja_money($allTotals['cash_net'])?></strong><span>Aportaciones y saldo inicial</span><strong>+ <?=caja_money($allTotals['mov_in'])?></strong><span>Retiradas de efectivo</span><strong>&minus; <?=caja_money($allTotals['mov_out'])?></strong><span class="total"><?=$closed?'Saldo te&oacute;rico tras retiradas':'Efectivo disponible'?></span><strong class="total"><?=caja_money($allTotals['cash'])?></strong><?php if($closed){ ?><span>Recuento registrado</span><strong><?=caja_money((int)round((float)$period['close']['importe_al_cierre_real']*100))?></strong><?php if((int)$period['close']['version_control']>=1){ ?><span>Saldo previsto antes del cierre</span><strong><?=caja_money((int)round((float)$period['close']['importe_al_cierre']*100))?></strong><span>Diferencia del recuento</span><strong><?=caja_money((int)round(((float)$period['close']['importe_al_cierre_real']-(float)$period['close']['importe_al_cierre'])*100))?></strong><?php } } ?></div><?php if($closed&&$period['close']['comentario']){ ?><p class="caja-note"><b>Comentarios:</b> <?=nl2br(app_escape($period['close']['comentario']))?></p><?php } ?></section><?php } ?></div>
<?php if(!$history){ ?><section class="caja-card"><h2>Aportaciones y retiradas de efectivo</h2><p class="caja-note">Movimientos completos del periodo, incluidos el saldo inicial y las retiradas al cierre.</p><div class="caja-rotate">Gira el dispositivo o desliza para ver todos los datos.<button type="button" data-landscape>Ver en horizontal</button></div><div class="caja-table-wrap"><table class="caja-table"><thead><tr><th>Fecha</th><th>Concepto</th><th>Registrado por</th><th class="number">Importe</th><th>Acciones</th></tr></thead><tbody><?php foreach($movements as $m){$initial=in_array($m['comentario'],['Importe inical de la caja','Importe inicial de la caja'],true); ?><tr><td class="date"><?=caja_date($m['fecha'])?><small><?=app_escape(substr((string)$m['hora'],0,5))?></small></td><td><?=app_escape($m['comentario'])?></td><td><?=app_escape(trim((string)$m['empleado'])?:'No disponible')?></td><td class="number <?=(int)$m['signo']<0?'caja-negative':'caja-positive'?>"><?=caja_money((int)round((float)$m['importe']*100)*(int)$m['signo'])?></td><td><?php if(!$closed&&!$initial){ ?><form method="post" class="caja-inline-form" action="eliminar_mov_caja.php" data-confirm="Se eliminar&aacute; este movimiento de efectivo. &iquest;Continuar?"><input type="hidden" name="id_centro_caja" value="<?=$centreId?>"><input type="hidden" name="id_mov" value="<?=(int)$m['id_movimiento']?>"><input type="hidden" name="caja_token" value="<?=caja_token('delete_cash',$centreId,$period['previous_id'])?>"><button class="danger" type="submit">Eliminar</button></form><?php }else{ ?><span class="caja-note"><?=$initial?'Saldo del cierre anterior':'Solo consulta'?></span><?php } ?></td></tr><?php }if(!$movements){ ?><tr><td colspan="5" class="caja-empty">Todav&iacute;a no hay aportaciones ni retiradas en este periodo.</td></tr><?php } ?></tbody></table></div></section><?php } ?>
<?php caja_footer(); ?>
